async function refreshDriveIndicator(){const target=document.getElementById('drive-connection');if(!target)return;const status=await driveStatus(chrome);if(status.status==='connected'&&!await chrome.permissions.contains({permissions:['identity'],origins:['https://www.googleapis.com/*']}))status.status='reconnect-required';const connected=status.status==='connected';const labels={connected:t("Connected"),connecting:t("Connecting…"),'reconnect-required':t("Reconnect required"),disconnected:t("Not connected")};target.dataset.connected=String(connected);target.replaceChildren(el('strong',{},labels[status.status]||t("Not connected")),el('span',{},status.account?.label||t("Connect your Google account to back up to Drive.")),el('small',{},t('Last backup: {date}',{date:status.lastBackupAt?date(status.lastBackupAt):t('No successful backup yet')})));const feedback=document.getElementById('drive-feedback');if(feedback)feedback.textContent=[translateError(status.error),status.pendingUpload?t("An upload may have completed. Review Google Drive backup before uploading again."):''].filter(Boolean).join(' ');document.querySelectorAll('[data-drive-connected]').forEach(b=>b.disabled=!connected||b.dataset.busy==='true');document.querySelectorAll('[data-drive-connect]').forEach(b=>{b.textContent=connected?t("Disconnect"):t("Connect Google Drive");b.disabled=status.status==='connecting'||b.dataset.busy==='true';});}
function summaryText(summary){return t('Bookmarks: {bookmarks} · Folders: {folders} · Favorites: {favorites} · With notes: {notes} · With tags: {tagged} · Preferences {preferences}',{...summary,preferences:t(summary.preferences?'included':'not included')});}
function storedSummary(properties){if(!properties)return null;const keys=['bookmarks','folders','favorites','notes','tagged'];if(!keys.every(k=>/^\d+$/.test(properties[k]||'')&&Number(properties[k])<=50000)||!['true','false'].includes(properties.preferences))return null;return {...Object.fromEntries(keys.map(k=>[k,Number(properties[k])])),preferences:properties.preferences==='true'};}
async function captureBackup(){return lib.serialize(async()=>makeExport(await lib.load(),(await chrome.storage.local.get('bookmarks.preferences.v1'))['bookmarks.preferences.v1']||{}));}
function driveList(history){const historyDialog=modal(t("Google Drive backups"),(dialog,form)=>{
 let chosen=null;
 const selectedSnapshot=()=>{if(!chosen)throw Error(t("Select a backup first."));return chosen;};
 const restore=button(t("Restore"),async()=>{const b=selectedSnapshot();const doc=await downloadBackup(chrome,b.id,fetch,history.generation);dialog.close();await previewImport({...doc,snapshotDetails:`${b.name||t("Backup")} · ${b.createdTime?date(b.createdTime):t("Date unavailable")}`});},{disabled:true,class:'primary'});
 const remove=button(t("Delete"),()=>{const b=selectedSnapshot();const confirmation=modal(t("Delete this cloud backup?"),(d,f)=>{f.append(el('p',{},b.name));return button(t("Confirm cloud deletion"),async()=>{await deleteBackup(chrome,b.id,fetch,history.generation);d.close();dialog.close();driveList(await listBackups(chrome));message(t("Cloud backup deleted."));},{class:'danger'});});confirmation.dataset.drive='true';},{disabled:true,class:'danger'});
 form.append(el('p',{},t("Select one backup, then choose Restore or Delete. Restore shows a preview before changing your library.")));
 const list=el('ul',{class:'snapshot-list','aria-label':t("Saved Google Drive backups")});
 if(!history.files.length)form.append(el('p',{},t("No backups found.")));
 for(const b of history.files){const summary=storedSummary(b.appProperties);const summaryNode=el('span',{class:'snapshot-summary'},summary?summaryText(summary):t("Older backup — counts available in the restore preview."));
 const select=el('input',{type:'radio',name:'drive-snapshot','aria-label':t('Select {title}',{title:b.name||t('Bookmark backup')}),onchange:()=>{chosen=b;restore.disabled=false;remove.disabled=false;}});
 list.append(el('li',{},el('label',{class:'snapshot-row'},select,el('span',{class:'snapshot-content'},el('strong',{},b.name||t("Bookmark backup")),el('span',{class:'snapshot-date'},`${b.createdTime?date(b.createdTime):t("Date unavailable")}${b.size?' · '+t('{count} KB',{count:Math.ceil(Number(b.size)/1024)}):''}${b.appProperties?.schema?' · '+t('Format {version}',{version:b.appProperties.schema}):''}`),summaryNode))));}
 form.append(list);
 return el('div',{class:'toolbar'},restore,remove,button(t("Close"),()=>dialog.close()));
 },{cancel:false});historyDialog.dataset.drive='true';}




async function start(){languageChoice=(await chrome.storage.local.get(LANGUAGE_KEY))[LANGUAGE_KEY]||'auto';await setLanguage(languageChoice);updateAnnouncement=installedVersion?await pendingVersionUpdate(chrome,installedVersion):null;document.title=t('1stTab Bookmarks');await initializeBookmarks(chrome);await lib.migrate();applyPrefs({...((await chrome.storage.local.get('bookmarks.preferences.v1'))['bookmarks.preferences.v1']||{}),view:'grid'});build();await refresh();message(t("Library ready."));lib.subscribe(()=>run(refresh));
const capture=(await chrome.storage.local.get('bookmarks.capture.v1'))['bookmarks.capture.v1'];if(capture&&Date.now()-capture.createdAt<300000){await chrome.storage.local.remove('bookmarks.capture.v1');editBookmark(null,capture)}chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&changes['bookmarks.preferences.v1'])applyPrefs(changes['bookmarks.preferences.v1'].newValue||{});});if(isSettingsRoute())showPage(true,false);}
systemDark.addEventListener('change',()=>{if(prefs.theme==='system')applyAppearance()});
narrow.addEventListener('change',()=>{mobileTreeOpen=false;if(state)renderFolders()});
run(start);

chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&changes[DRIVE_KEY])run(refreshDriveIndicator);if(area==='local'&&changes[DRIVE_KEY]&&changes[DRIVE_KEY].oldValue?.generation!==changes[DRIVE_KEY].newValue?.generation){document.querySelectorAll('dialog[open][data-drive]').forEach(d=>d.close());}});

document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(settingsOpen)showLibrary();document.getElementById('search')?.focus()}if(e.key==='Escape'){finishDrag();mobileTreeOpen=false;if(state)renderFolders()}});

function rebuildLanguage(){
 updateLanguageBindings();const open=settingsOpen,position=scrollY;build();
 document.getElementById('search').value=filter.query;
 document.getElementById('tag-filter').value=filter.tag;
  document.getElementById('domain-filter').value=filter.domain;
 renderResults();renderFolders();showPage(open,false);window.scrollTo(0,position);
}
chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&changes[LANGUAGE_KEY])run(async()=>{languageChoice=changes[LANGUAGE_KEY].newValue||'auto';if(await setLanguage(languageChoice))rebuildLanguage();const select=document.getElementById('language-choice');if(select)select.value=languageChoice;});});

window.addEventListener('resize',syncResizeHandle);
